def transform(grid):
    """Recolor every other 4-connected component of 2s, counting from the right."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            components.append(cells)
    components.sort(key=lambda cells: min(c for r,c in cells))
    out = [row[:] for row in grid]
    # The rightmost component is 8; alternate as we move left.
    for k, cells in enumerate(reversed(components)):
        if k % 2 == 0:
            for r, c in cells:
                out[r][c] = 8
    return out
